import os


class Config:
    # --------------------------------------------------------------------------
    # Directory and File Paths
    # --------------------------------------------------------------------------
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_6"
    OUTPUT_DIR = "./submission"

    # Ensure working and output directories exist
    os.makedirs(WORKING_DIR, exist_ok=True)
    os.makedirs(OUTPUT_DIR, exist_ok=True)

    # Metadata Paths (Generated by the provided metadata script)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Tracking Data Paths
    TRAIN_TRACKING_PATH = os.path.join(INPUT_DIR, "train_player_tracking.csv")
    TEST_TRACKING_PATH = os.path.join(INPUT_DIR, "test_player_tracking.csv")

    # Submission Path
    SUBMISSION_PATH = os.path.join(OUTPUT_DIR, "submission.csv")

    # --------------------------------------------------------------------------
    # Global Settings
    # --------------------------------------------------------------------------
    SEED = 42
    N_JOBS = 12  # Utilizing available vCPUs

    # --------------------------------------------------------------------------
    # Feature Engineering Parameters
    # --------------------------------------------------------------------------
    # Temporal Window: +/- 10 steps (1.0 second context around the event)
    WINDOW_SIZE = 10

    # Spatial Density Radius (yards) for calculating neighbor counts and cluster kinematics
    NEIGHBOR_RADIUS = 2.0

    # Feature Flags
    USE_JERK = True  # Calculate derivative of acceleration
    USE_CLUSTER_KINEMATICS = True  # Calculate avg velocity/accel of local cluster

    # --------------------------------------------------------------------------
    # Data Selection & Mining Parameters
    # --------------------------------------------------------------------------
    # Scout Stage: Ratio of Random Negatives to Positives to train the filter
    SCOUT_NEG_RATIO = 5

    # Expert Stage: Ratio of Random Negatives to Positives (Hard negatives are added on top)
    EXPERT_RANDOM_NEG_RATIO = 1

    # Threshold to consider a negative as "Hard" during mining
    # If Scout predicts probability > this value for a negative sample, it is mined.
    HARD_NEGATIVE_THRESHOLD = 0.05

    # --------------------------------------------------------------------------
    # Model Hyperparameters
    # --------------------------------------------------------------------------

    # 1. Scout Model (Lightweight LightGBM)
    # Optimized for speed and high recall to identify potential candidates
    LGBM_SCOUT_PARAMS = {
        "objective": "binary",
        "metric": "binary_logloss",
        "boosting_type": "gbdt",
        "learning_rate": 0.1,
        "num_leaves": 31,
        "max_depth": 7,
        "feature_fraction": 0.8,
        "bagging_fraction": 0.8,
        "bagging_freq": 5,
        "n_estimators": 500,
        "verbose": -1,
        "n_jobs": N_JOBS,
        "seed": SEED,
        "is_unbalance": True,  # Crucial for recall in the filtering stage
    }

    # 2. Expert Model: LightGBM
    # High capacity, deep trees for complex boundary resolution
    LGBM_EXPERT_PARAMS = {
        "objective": "binary",
        "metric": "binary_logloss",
        "boosting_type": "gbdt",
        "learning_rate": 0.05,
        "num_leaves": 256,  # High capacity
        "max_depth": 10,  # Deeper trees
        "feature_fraction": 0.7,
        "bagging_fraction": 0.8,
        "bagging_freq": 5,
        "n_estimators": 2000,
        "verbose": -1,
        "n_jobs": N_JOBS,
        "seed": SEED,
        "is_unbalance": True,  # Handling remaining imbalance
    }

    # 3. Expert Model: XGBoost
    # Heterogeneous ensemble partner
    XGB_EXPERT_PARAMS = {
        "objective": "binary:logistic",
        "eval_metric": "logloss",
        "learning_rate": 0.05,
        "max_depth": 10,
        "max_leaves": 256,  # Consistent capacity with LGBM
        "subsample": 0.8,
        "colsample_bytree": 0.7,
        "n_estimators": 2000,
        "n_jobs": N_JOBS,
        "random_state": SEED,
        "tree_method": "hist",  # Faster training on large datasets
        # scale_pos_weight is typically handled dynamically or set to ~10-20 depending on mining results
    }

    # Early stopping rounds for training loops
    EARLY_STOPPING_ROUNDS = 100
